import { useMemo } from 'react';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { useIssuedVoucherListInfiniteQuery } from '~/entities/voucher/api/hooks/use-issued-voucher-list-infinite-query';
import { VOUCHER_LIST_PAGING } from '~/entities/voucher/model/constants';
import { VoucherProcSttusCd, VoucherUseYn } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { SelectOption } from '~/shared/ui/selects/base/types';

export const useVoucherOptions = (placeId?: string, aliasNm?: string | null) => {
  const { data: userRes } = useGetUserInfoQuery();
  const cstmrNo = userRes?.tbCstmrMastr?.cstmrNo ?? null;

  const { data: allVoucher } = useIssuedVoucherListInfiniteQuery({
    paging: { ...VOUCHER_LIST_PAGING },
    cstmrNo,
    aliasNm: aliasNm ?? userRes?.tbCstmrMastr?.aliasNm ?? 'ALL',
  });

  const defaultOption = useMemo(
    () => ({
      value: null as unknown as VoucherItemDTO,
      label: i18n.t('notApply'),
    }),
    [],
  );

  const options = useMemo(
    () => [
      defaultOption,
      ...(allVoucher?.pages.map((page) => page.result.list).flat() || [])
        .filter(
          (voucher) =>
            voucher.vouchId &&
            voucher.vouchNm &&
            voucher.useYn === VoucherUseYn.사용가능 &&
            (!placeId || voucher.place?.some((place) => place.placeId === placeId)),
        )
        .map((voucher) => ({
          value: voucher,
          label: voucher.vouchNm!,
          description: `${voucher.vouchTyNm} / ${voucher.pymntCond}` || undefined,
          disabled: voucher.vouchProcSttusCd !== VoucherProcSttusCd.사용 || (Number(voucher?.pbmBalanceOf) || 0) <= 0,
        })),
    ],
    [allVoucher?.pages, defaultOption, placeId],
  );

  const getSelectedOption = (vouchId: string | null): SelectOption<VoucherItemDTO> => {
    if (!vouchId) return defaultOption;

    const selectedVoucher = allVoucher?.pages
      .map((page) => page.result.list)
      .flat()
      .find((item) => item.vouchId === vouchId);

    if (!selectedVoucher) return defaultOption;

    return {
      value: selectedVoucher,
      label: selectedVoucher.vouchNm ?? '',
      description: `${selectedVoucher.vouchTyNm}/${selectedVoucher.pymntCond}` || undefined,
    };
  };

  return {
    options,
    defaultOption,
    getSelectedOption,
  };
};
